<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use DateTime;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Usecase\Update\UserFederatedIdentityUpdateUsecase;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentityUidVO;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentityUserVO;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentityLoginProviderVO;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\TenantLoginProviderRef;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentitySubjectVO;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentityVersionVO;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Usecase\Update\UserFederatedIdentityUpdateParams;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Usecase\Update\UserFederatedIdentityUpdateResult;

class UserFederatedIdentityUpdateController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly SqlTemplate $sql,
        private readonly UserFederatedIdentityUpdateUsecase $updateUsecase,
    ) {
    }
    #[OA\Put(
        path: "/api/access/user-federated-identities/{uid}",
        tags: ["User federated identity"],
        description: "Update the value",
        parameters: [
        new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
    ],
        requestBody: new OA\RequestBody(content: new OA\JsonContent(type: "object", ref:"#/components/schemas/UserFederatedIdentityApiDTO")),
        responses: [
        new OA\Response(response: 200, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/UserFederatedIdentityApiDTO")),
        new OA\Response(response: 404, description: "Not found"),
        new OA\Response(response: 409, description: "Optimist lock"),
        new OA\Response(response: 422, description: "Constraint error"),
    ]
    )
    ]
    public function update(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Update User federated identity");
        $span = $this->startSpan("Update User federated identity");
        $this->sql->begin();
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $value = $this->readUserFederatedIdentity($request);
            $result = $this->updateUsecase->update($uid, $value);
            $this->sql->commit();
            $value = $this->mapUserFederatedIdentity($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
                  ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $this->sql->close();
            $span->end();
        }
    }

    private function readUserFederatedIdentity(ServerRequestInterface $request): UserFederatedIdentityUpdateParams
    {
        $this->logDebug("Read entity for User federated identity");
        $span = $this->startSpan("Read entity for User federated identity");
        try {
            $parsed = $request->getParsedBody() ?? [];
            $body = is_array($parsed) ? $parsed : get_object_vars($parsed);
            $errorsList = new ConstraintFailList();
            $value = new UserFederatedIdentityUpdateParams();
            $valueUid = UserFederatedIdentityUidVO::tryFrom($body['uid'] ?? null, $errorsList);
            if (null !== $valueUid) {
                $value->uid($valueUid);
            }
            if (in_array('user', array_keys($body))) {
                $valueUser = UserFederatedIdentityUserVO::tryFrom(isset($body['user']['$ref']) ? new UserRef($body['user']['$ref']) : null, $errorsList);
                if (null !== $valueUser) {
                    $value->user($valueUser);
                }
            }
            if (in_array('loginProvider', array_keys($body))) {
                $valueLoginProvider = UserFederatedIdentityLoginProviderVO::tryFrom(isset($body['loginProvider']['$ref']) ? new TenantLoginProviderRef($body['loginProvider']['$ref']) : null, $errorsList);
                if (null !== $valueLoginProvider) {
                    $value->loginProvider($valueLoginProvider);
                }
            }
            $valueSubject = UserFederatedIdentitySubjectVO::tryFrom($body['subject'] ?? null, $errorsList);
            if (null !== $valueSubject) {
                $value->subject($valueSubject);
            }
            $value->version(UserFederatedIdentityVersionVO::tryFrom($body['version'] ?? null, $errorsList));
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            return $value;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function mapUserFederatedIdentity(ServerRequestInterface $request, UserFederatedIdentityUpdateResult $value): UserFederatedIdentityApiDTO
    {
        $this->logDebug("Map entity to output dto for User federated identity");
        $span = $this->startSpan("Map entity to output dto for User federated identity");
        try {
            $user = $value->getUser();
            $loginProvider = $value->getLoginProvider();
            $dto = new UserFederatedIdentityApiDTO();
            $dto->uid = $value->getUid();
            $dto->user = $user ? ['$ref' => $user->uid()] : null;
            $dto->loginProvider = $loginProvider ? ['$ref' => $loginProvider->uid()] : null;
            $dto->subject = $value->getSubject();
            $dto->createdAt = $value->getCreatedAt()?->format(DateTime::ATOM);
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
